class Solution {
    public String minRemoveToMakeValid(String s){
        boolean[] remove=new boolean[s.length()];
        Deque<Integer> stack=new ArrayDeque<>();
        for(int i=0;i<s.length();i++)if(s.charAt(i)=='(')stack.push(i);
        else if(s.charAt(i)==')'){
            if(stack.isEmpty())remove[i]=true;
            else stack.pop();
        }while(!stack.isEmpty())remove[stack.pop()]=true;
        StringBuilder answer=new StringBuilder();
        for(int i=0;i<s.length();i++)if(!remove[i])answer.append(s.charAt(i));
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun minRemoveToMakeValid(s:String):String{
        val remove=BooleanArray(s.length);
        val stack=java.util.ArrayDeque<Int>();
        for(i in s.indices)if(s[i]=='(')stack.push(i)else if(s[i]==')'){
            if(stack.isEmpty())remove[i]=true else stack.pop()
        };
        while(stack.isNotEmpty())remove[stack.pop()]=true;
        return buildString{
            for(i in s.indices)if(!remove[i])append(s[i])
        }
    }
}

